CREATE TABLE IF NOT EXISTS vehicle(id VARCHAR(36) PRIMARY KEY,tenant_id VARCHAR(80) NOT NULL,plate VARCHAR(30) NOT NULL,driver VARCHAR(80) NOT NULL,capacity_kg BIGINT NOT NULL,used_kg BIGINT NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(tenant_id,plate));
CREATE TABLE IF NOT EXISTS assignment(id VARCHAR(36) PRIMARY KEY,tenant_id VARCHAR(80) NOT NULL,shipment_id VARCHAR(36) NOT NULL,user_id VARCHAR(80) NOT NULL,vehicle_id VARCHAR(36) NOT NULL,weight_kg BIGINT NOT NULL,state VARCHAR(20) NOT NULL,UNIQUE(tenant_id,shipment_id));
CREATE TABLE IF NOT EXISTS release_marker(tenant_id VARCHAR(80) NOT NULL,shipment_id VARCHAR(36) NOT NULL,PRIMARY KEY(tenant_id,shipment_id));
CREATE TABLE IF NOT EXISTS callbacks(id VARCHAR(36) PRIMARY KEY,tenant_id VARCHAR(80) NOT NULL,shipment_id VARCHAR(36) NOT NULL,vehicle_id VARCHAR(36) NOT NULL,trace_id VARCHAR(80) NOT NULL,state VARCHAR(20) NOT NULL,attempts INT NOT NULL DEFAULT 0,next_at BIGINT NOT NULL);
